local function is_true(v)
	return v == true or v == 1
end

-- schneller Base64-Decoder (ohne externe Bibliotheken)
local B64 = {}

do
	local chars = "ABCDEFGHIJKLMNOPQRSTUVWXYZabcdefghijklmnopqrstuvwxyz0123456789+/"

	for i = 1, #chars do
		B64[chars:byte(i)] = i - 1
	end
end

local function decode_base64(data)
	local out, n = {}, 0

	for i = 1, #data, 4 do
		local a, b, c, d = data:byte(i, i + 3)
		local v = B64[a] * 262144 + B64[b] * 4096 + (B64[c] or 0) * 64 + (B64[d] or 0)

		n = n + 1

		if c == nil or c == 61 then
			out[n] = string.char(math.floor(v / 65536))
		elseif d == nil or d == 61 then
			out[n] = string.char(math.floor(v / 65536), math.floor(v / 256) % 256)
		else
			out[n] = string.char(math.floor(v / 65536), math.floor(v / 256) % 256, v % 256)
		end
	end

	return table.concat(out)
end

-- Overshoot-Easing (0 -> kurz über 1 -> 1)
local function ease_out_back(x, c1)
	c1 = c1 or 2.0

	local c3 = c1 + 1

	x = x - 1

	return 1 + c3 * x * x * x + c1 * x * x
end

-- Sichtbarkeit der Einstellungen eines Moduls an die Haupt-Checkbox koppeln
local function bind_module(group, on_change)
	local function update()
		local on = ui.get(group.enabled)

		for key, item in pairs(group) do
			if key ~= "enabled" and key ~= "header" then
				ui.set_visible(item, on)
			end
		end

		if on_change then
			on_change(on)
		end
	end

	ui.set_callback(group.enabled, update)
	update()
end

