local DIGIT_W  = 59    -- Breite einer Ziffer (für den Abstand)
local TEX_SIZE = 124   -- Kantenlänge der vorgedrehten Ziffern-Bilder
local ROT_STEP = 10    -- Grad pro vorgedrehtem Frame
local ROT_MAX  = 9     -- max. Frames pro Richtung (9 * 10° = 90°)

local DMG = {
	design_life = 1.5,   -- Referenzdauer in s, auf die die Bewegung abgestimmt ist
	pop_time    = 0.14,  -- Dauer des Aufpoppens
	hold_time   = 0.27,  -- so lange bleibt die Zahl als Block zusammen
	float_up    = 28,    -- sanftes Hochschweben während der Block zusammen ist (px)
	push_min    = 90,    -- seitliche Geschwindigkeit der Hälften nach dem Split (px/s)
	push_max    = 130,
	hop_min     = 140,   -- kleiner Hüpfer nach oben beim Split (px/s)
	hop_max     = 240,
	gravity     = 1500,  -- Schwerkraft (px/s²)
	fade_start  = 0.30,  -- ab wann (Anteil der Lebenszeit) die Auflösung beginnt
	shrink      = 0.45,  -- wie stark die Hälften beim Zerfallen schrumpfen
	rot_min     = 90,    -- Drehgeschwindigkeit der Ziffern beim Fallen (Grad/s)
	rot_max     = 140,
	head_size   = 1.2,   -- Headshot-Zahlen sind etwas größer
	spacing     = 0.9    -- Abstand der Ziffern (1.0 = Bildbreite, kleiner = enger)
}

-- textures[Ziffer][Frame]: Frame -ROT_MAX..ROT_MAX
-- negativ = gegen den Uhrzeigersinn (linke Hälfte), positiv = im Uhrzeigersinn (rechte Hälfte)
local textures = {}

for d = 0, 9 do
	textures[d] = {}

	for k = -ROT_MAX, ROT_MAX do
		textures[d][k] = renderer.load_png(decode_base64(frames[d + 1][k + ROT_MAX + 1]), TEX_SIZE, TEX_SIZE)
	end
end

frames = nil

local hits = {}
local MAX_HITS = 48

local attacker_filter = {
	Player    = function(ent) return entity.get_local_player() == ent end,
	Teammates = function(ent) return not entity.is_enemy(ent) end,
	Enemies   = function(ent) return entity.is_enemy(ent) end
}

local function draw_digit(digit, frame, cx, cy, scale, r, g, b, a)
	local size = TEX_SIZE * scale

	renderer.texture(textures[digit][frame], cx - size / 2, cy - size / 2, size, size, r, g, b, a, "f")
end

-- erzeugt eine neue Schadenszahl, aufgeteilt in eine linke und eine rechte Hälfte
local function spawn_hit(x, y, z, damage, headshot, shield)
	local text = string.format("%d", damage)
	local n = #text
	local left_count = math.ceil(n / 2)   -- 3 Ziffern: 2 links, 1 rechts
	local digits = {}

	for i = 1, n do
		digits[i] = {
			digit = tonumber(text:sub(i, i)),
			group = i <= left_count and 1 or 2,
			rot = client.random_float(DMG.rot_min, DMG.rot_max)
		}
	end

	-- Hälften: [1] fliegt nach links, [2] nach rechts
	local groups = {
		{vx = -client.random_float(DMG.push_min, DMG.push_max), vy = -client.random_float(DMG.hop_min, DMG.hop_max)},
		{vx =  client.random_float(DMG.push_min, DMG.push_max), vy = -client.random_float(DMG.hop_min, DMG.hop_max)}
	}

	-- einstellige Zahl: es gibt nur einen Block, der in eine zufällige Richtung fliegt
	if n == 1 then
		digits[1].group = client.random_int(1, 2)
	end

	if #hits >= MAX_HITS then
		table.remove(hits, 1)
	end

	hits[#hits + 1] = {
		t0 = globals.realtime(),
		x = x, y = y, z = z,
		ox = client.random_float(-12, 12),
		oy = client.random_float(-8, 8),
		head = headshot,
		shield = shield,
		digits = digits,
		groups = groups
	}
end

local function draw_hit(hit, now, life, k, colors)
	local sx, sy = renderer.world_to_screen(hit.x, hit.y, hit.z)

	if sx == nil then
		return
	end

	local t = now - hit.t0                      -- echte Zeit
	local ph = t * (DMG.design_life / life)     -- Animationszeit (skaliert mit dem Zeit-Slider)

	local col = hit.shield and colors.shield or (hit.head and colors.head or colors.body)
	local size = k * 0.5 * (hit.head and DMG.head_size or 1)
	local step = DIGIT_W * size * DMG.spacing
	local n = #hit.digits

	-- Auflösung: 0 = voll da, 1 = komplett weg
	local decay = math.max(0, (t / life - DMG.fade_start) / (1 - DMG.fade_start))
	local alpha = math.floor(col[4] * (1 - decay * decay) + 0.5)
	local shrink = 1 - DMG.shrink * decay

	if alpha <= 0 then
		return
	end

	sx = sx + hit.ox * k
	sy = sy + hit.oy * k

	-- Phase 1: Block schwebt sanft nach oben (ease-out)
	local hold_t = math.min(ph / DMG.hold_time, 1)
	local float = -DMG.float_up * (1 - (1 - hold_t) * (1 - hold_t))

	-- Phase 2: nach dem Split bewegen sich die beiden Hälften
	local ts = math.max(0, ph - DMG.hold_time)

	-- Pop gilt für den ganzen Block (Abstand + Größe), danach 1.0
	local pop = ease_out_back(math.min(ph / DMG.pop_time, 1), 2.4)

	for i = 1, n do
		local d = hit.digits[i]
		local g = hit.groups[d.group]

		local cx = sx + (i - (n + 1) / 2) * step * pop + g.vx * ts * k
		local cy = sy + (float + g.vy * ts + 0.5 * DMG.gravity * ts * ts) * k

		-- Drehung: linke Hälfte gegen, rechte Hälfte im Uhrzeigersinn
		local frame = math.min(math.floor(ts * d.rot / ROT_STEP + 0.5), ROT_MAX)

		if d.group == 1 then
			frame = -frame
		end

		draw_digit(d.digit, frame, cx, cy, size * pop * shrink, col[1], col[2], col[3], alpha)
	end
end

local function dmg_on_player_hurt(e)
	if not ui.get(ui_dmg.enabled) then
		return
	end

	local attacker = client.userid_to_entindex(e.attacker)

	if attacker == 0 then
		return
	end

	for _, name in ipairs(ui.get(ui_dmg.mode)) do
		if attacker_filter[name](attacker) then
			local victim = client.userid_to_entindex(e.userid)
			local x, y, z = entity.hitbox_position(victim, 0)

			if x ~= nil then
				-- blau, wenn Rüstung/Helm den Treffer abgefangen hat
				spawn_hit(x, y, z, e.dmg_health, e.hitgroup == 1, e.dmg_armor > 0)
			end

			return
		end
	end
end

local function dmg_on_paint()
	if #hits == 0 or not ui.get(ui_dmg.enabled) then
		return
	end

	local now = globals.realtime()
	local life = ui.get(ui_dmg.timeout) * 0.1
	local k = ui.get(ui_dmg.scale) / 100

	local br, bg, bb, ba = ui.get(ui_dmg.body_color)
	local hr, hg, hb, ha = ui.get(ui_dmg.head_color)
	local sr, sg, sb, sa = ui.get(ui_dmg.shield_color)
	local colors = {
		body = {br, bg, bb, ba},
		head = {hr, hg, hb, ha},
		shield = {sr, sg, sb, sa}
	}

	for i = #hits, 1, -1 do
		local hit = hits[i]

		if now - hit.t0 >= life then
			table.remove(hits, i)
		else
			draw_hit(hit, now, life, k, colors)
		end
	end
end

