-- FFI: Font-Datei in Windows GDI registrieren
pcall(ffi.cdef, [[
	int AddFontResourceA(const char* lpszFilename);
	int AddFontResourceExA(const char* name, uint32_t fl, void* res);
]])

pcall(function()
	ffi.C.AddFontResourceA("BurbankBigCondensed-Black.otf")
	ffi.C.AddFontResourceExA("BurbankBigCondensed-Black.otf", 0x10, nil)
end)

local KN = {
	pop_time   = 0.18,  -- Dauer des Einpoppens (groß -> normal)
	pop_scale  = 0.55,  -- Start-Größe: 1.55x, schrumpft mit Überschwingen auf 1.0
	fade_in    = 0.08,  -- Einblenden
	fade_out   = 0.30,  -- Ausblenden am Ende der Anzeigedauer
	stagger    = 0.04,  -- Verzögerung zwischen KNOCKED / DOWN / Name
	drift      = 4,     -- langsames Hochschweben während der Anzeige (px/s)
	out_lift   = 14,    -- zusätzliches Hochziehen beim Ausblenden (px)
	out_shrink = 0.08,  -- Schrumpfen beim Ausblenden
	shadow     = 2,     -- Schatten-Versatz in px (0 = aus)
	gap_words  = 5,     -- Abstand zwischen KNOCKED und DOWN
	gap_name   = 16,    -- Abstand zum Spielernamen
	y_pos      = 0.72,  -- Höhe auf dem Bildschirm (72%)
	queue_gap  = 0.06,  -- kurze Pause zwischen zwei Meldungen
	max_queue  = 8      -- max. wartende Meldungen
}

-- Fonts in mehreren Größen (damit der Pop-Effekt skalieren kann)
local SCALE_MIN, SCALE_STEP, SCALE_COUNT = 0.90, 0.05, 15   -- 0.90x ... 1.60x

local fonts = { knock = {}, thin = {} }

if success_surface and surface then
	for i = 1, SCALE_COUNT do
		local s = SCALE_MIN + (i - 1) * SCALE_STEP

		-- Burbank Font (28px Basis)
		fonts.knock[i] = surface.create_font("Burbank Big Cd Bk", math.floor(28 * s + 0.5), 800, {0x010, 0x001})
		-- Dünne OG Font (25px Basis, Clean Sans-Serif)
		fonts.thin[i] = surface.create_font("Arial", math.floor(25 * s + 0.5), 400, {0x010})
	end
end

local use_surface = success_surface and surface and fonts.knock[1] and fonts.thin[1]

local function font_for(set, scale)
	local i = math.floor((scale - SCALE_MIN) / SCALE_STEP + 0.5) + 1

	return set[math.max(1, math.min(SCALE_COUNT, i))]
end

-- Textgrößen zwischenspeichern (spart Aufrufe pro Frame)
local size_cache, size_cache_n = {}, 0

local function text_size(font, text)
	local key = font .. "|" .. text
	local c = size_cache[key]

	if not c then
		local w, h = surface.get_text_size(font, text)

		if size_cache_n > 500 then
			size_cache, size_cache_n = {}, 0
		end

		c = {w, h}
		size_cache[key] = c
		size_cache_n = size_cache_n + 1
	end

	return c[1], c[2]
end

-- Queue: jede Meldung wird komplett angezeigt, dann die nächste
local queue = {}
local current = nil
local next_allowed = 0

local function clear_notifications()
	queue = {}
	current = nil
	next_allowed = 0
end

local function draw_notification(n, now, duration)
	local t = now - n.start
	local sw, sh = client.screen_size()

	-- Ausblenden am Ende
	local out_p = math.max(0, (t - (duration - KN.fade_out)) / KN.fade_out)
	out_p = math.min(out_p, 1)

	local out_alpha = 1 - out_p
	local out_scale = 1 - KN.out_shrink * out_p
	local cy = sh * KN.y_pos - t * KN.drift - KN.out_lift * out_p * out_p

	-- Aktionstext ist IMMER Weiß (Farbe einstellbar)
	local tr, tg, tb = ui.get(ui_kn.text_color)

	-- Name ist ROT bei Eliminated, sonst GELB
	local nr, ng, nb
	if n.text == "ELIMINATED" then
		nr, ng, nb = ui.get(ui_kn.elim_color)
	else
		nr, ng, nb = ui.get(ui_kn.name_color)
	end

	if not use_surface then
		-- Fallback ohne Surface-Library
		local str_full = n.text .. " " .. n.name
		local w1 = renderer.measure_text("b", str_full)
		local a = math.floor(255 * math.min(1, t / KN.fade_in) * out_alpha)

		renderer.text((sw / 2) - (w1 / 2), cy, tr, tg, tb, a, "b", 0, str_full)
		return
	end

	local action_set = (ui.get(ui_kn.style) == "OG Classic (Thin Knock + Burbank Name)") and fonts.thin or fonts.knock

	-- Bestandteile der Zeile (delay = gestaffeltes Einpoppen)
	local parts
	if n.text:find("KNOCKED") then
		parts = {
			{text = "KNOCKED", set = action_set,  r = tr, g = tg, b = tb, delay = 0,              gap = KN.gap_words},
			{text = "DOWN",    set = action_set,  r = tr, g = tg, b = tb, delay = KN.stagger,     gap = KN.gap_name},
			{text = n.name,    set = fonts.knock, r = nr, g = ng, b = nb, delay = KN.stagger * 2, gap = 0}
		}
	else
		parts = {
			{text = n.text, set = action_set,  r = tr, g = tg, b = tb, delay = 0,          gap = KN.gap_name},
			{text = n.name, set = fonts.knock, r = nr, g = ng, b = nb, delay = KN.stagger, gap = 0}
		}
	end

	-- Größe jedes Teils im aktuellen Animationszustand bestimmen
	local total_w = 0

	for _, p in ipairs(parts) do
		local pt = math.max(0, t - p.delay)
		local e = ease_out_back(math.min(pt / KN.pop_time, 1), 2.0)
		local scale = (1 + KN.pop_scale * (1 - e)) * out_scale

		p.font = font_for(p.set, scale)
		p.alpha = math.min(1, pt / KN.fade_in) * out_alpha
		p.w, p.h = text_size(p.font, p.text)

		total_w = total_w + p.w + p.gap
	end

	local x = (sw / 2) - (total_w / 2)

	for _, p in ipairs(parts) do
		local a = math.floor(255 * p.alpha + 0.5)

		if a > 0 then
			local y = cy - p.h / 2

			if KN.shadow > 0 then
				surface.draw_text(x + KN.shadow, y + KN.shadow, 0, 0, 0, math.floor(a * 0.5), p.font, p.text)
			end

			surface.draw_text(x, y, p.r, p.g, p.b, a, p.font, p.text)
		end

		x = x + p.w + p.gap
	end
end

local function kn_on_paint()
	if not ui.get(ui_kn.enabled) then
		return
	end

	local now = globals.realtime()
	local duration = ui.get(ui_kn.time) * 0.1

	-- aktuelle Meldung ist fertig -> nächste darf kommen
	if current and now - current.start >= duration then
		current = nil
		next_allowed = now + KN.queue_gap
	end

	if not current and #queue > 0 and now >= next_allowed then
		current = table.remove(queue, 1)
		current.start = now
	end

	if current then
		draw_notification(current, now, duration)
	end
end

local function kn_on_player_death(e)
	if not ui.get(ui_kn.enabled) then
		return
	end

	local victim = client.userid_to_entindex(e.userid)
	local attacker = client.userid_to_entindex(e.attacker)
	local local_player = entity.get_local_player()

	if attacker == local_player and victim ~= local_player then
		local mode = ui.get(ui_kn.text_mode)
		local knock_text = "KNOCKED DOWN"

		if mode == "ELIMINATED" then
			knock_text = "ELIMINATED"
		elseif mode == "AUTO (Knock/Kill)" then
			knock_text = is_true(e.headshot) and "ELIMINATED" or "KNOCKED DOWN"
		end

		-- hinten anstellen; wenn zu viele warten, fliegt die älteste wartende raus
		if #queue >= KN.max_queue then
			table.remove(queue, 1)
		end

		queue[#queue + 1] = {
			text = knock_text,
			name = string.upper(entity.get_player_name(victim) or "PLAYER"),
			start = 0
		}
	end
end

-- ============================================================
--  3) HEADSHOT SOUND
-- ============================================================
local SOUND_FILE = "fn_headshot.wav"

-- Die WAV wird beim Laden automatisch nach csgo/sound/ geschrieben,
-- falls sie dort noch nicht liegt. Klappt das nicht, einfach
-- fn_headshot.wav von Hand nach  Counter-Strike Global Offensive/csgo/sound/  kopieren.
local function install_sound()
	local candidates = {"csgo/sound/" .. SOUND_FILE, "sound/" .. SOUND_FILE}

	local function installed(path)
		local ok, existing = pcall(readfile, path)

		return ok and existing ~= nil and #existing == WAV_LEN
	end

	for _, path in ipairs(candidates) do
		if installed(path) then
			return true
		end
	end

	local data = decode_base64(WAV_B64)

	for _, path in ipairs(candidates) do
		pcall(writefile, path, data)

		if installed(path) then
			return true
		end
	end

	return false
end

local sound_ok = install_sound()

if not sound_ok then
	client.color_log(255, 200, 0, "[Fortnite Pack] Konnte " .. SOUND_FILE .. " nicht automatisch installieren - bitte von Hand nach csgo/sound/ kopieren.")
end

play_headshot_sound = function()
	local volume = ui.get(ui_hs.volume) / 100

	client.exec(string.format('playvol "%s" %.2f', SOUND_FILE, volume))
end

local function hs_on_player_hurt(e)
	if not ui.get(ui_hs.enabled) or ui.get(ui_hs.trigger) ~= "Headshot hit" then
		return
	end

	local attacker = client.userid_to_entindex(e.attacker)
	local victim = client.userid_to_entindex(e.userid)

	if attacker == entity.get_local_player() and victim ~= attacker and e.hitgroup == 1 then
		play_headshot_sound()
	end
end

local function hs_on_player_death(e)
	if not ui.get(ui_hs.enabled) or ui.get(ui_hs.trigger) ~= "Headshot kill" then
		return
	end

	local attacker = client.userid_to_entindex(e.attacker)
	local victim = client.userid_to_entindex(e.userid)

	if attacker == entity.get_local_player() and victim ~= attacker and is_true(e.headshot) then
		play_headshot_sound()
	end
end

