bind_module(ui_dmg, function(on)
	hits = {}
end)

bind_module(ui_kn, function(on)
	clear_notifications()
end)

bind_module(ui_hs)

client.set_event_callback("player_hurt", dmg_on_player_hurt)
client.set_event_callback("player_hurt", hs_on_player_hurt)
client.set_event_callback("player_death", kn_on_player_death)
client.set_event_callback("player_death", hs_on_player_death)
client.set_event_callback("paint", dmg_on_paint)
client.set_event_callback("paint", kn_on_paint)
client.set_event_callback("round_start", function()
	hits = {}
	clear_notifications()
end)
